// Build the HTML email body from the rewritten newsletter sections
const items = $input.all();
const rewritten = items[0].json['message'] ? items[0].json['message']['content'] : items[0].json.output;
const date = new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"></head>
<body style="font-family: Georgia, serif; max-width: 640px; margin: 0 auto; padding: 24px; color: #1a1a1a;">
  <h1 style="font-size: 28px; border-bottom: 3px solid #111; padding-bottom: 12px;">The AI Brief — ${date}</h1>
  <p style="color: #555;">Your weekly roundup of the stories that matter, curated and rewritten for busy founders.</p>
  <div style="margin-top: 24px; white-space: pre-wrap;">${rewritten}</div>
  <hr style="margin: 32px 0; border: none; border-top: 1px solid #ddd;">
  <p style="font-size: 12px; color: #999;">Sent automatically by the AI Newsletter Pipeline. Reply to this email with feedback or topics you want covered.</p>
</body></html>`;
return [{ json: { htmlBody: html } }];

// Log the successful send for audit purposes
const now = new Date().toISOString();
console.log(`[${now}] Newsletter sent to ${$env.NEWSLETTER_TO || 'you@example.com'}`);
return $input.all();
